<?php get_header();$news=new WP_Query(array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>12,'paged'=>max(1,get_query_var('paged'))));?><header class="gmr-archive-head"><div class="gmr-wrap"><span class="gmr-kicker">Actualidad de la galeria</span><h1 class="gmr-page-title">Noticias</h1></div></header><section class="gmr-section"><div class="gmr-wrap gmr-editorial-grid"><?php if($news->have_posts()):while($news->have_posts()):$news->the_post();get_template_part('template-parts/story','card');endwhile;else:?><p class="gmr-empty">El archivo de noticias se encuentra en preparacion.</p><?php endif;wp_reset_postdata();?></div></section><?php get_footer();?>
